package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.jobs.ResultApplicationService.Input;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.node.ObjectNode;
import tools.jackson.databind.json.JsonMapper;

/** Actual immutable original INPUT storage/current proof and first-ledger priority. No new claim/request/model result authorization. */
class CatalogVersionBatchPreflightTest extends CatalogVersionJudgmentValueTest {
    Input original;String originalJson;CatalogVersionQualificationProjection.Projection previous;final String root="fictional-catalog-dedup-root";
    void seed(boolean unknown,boolean frame){var p=projection();previous=p;var fake=input(p);var context=new FrozenCatalogVersionContextTest().context(fake.stage());context.putArray("item_ids").add(p.memberId());context.putArray("eligible_high_value_item_ids");context.putArray("candidates_by_item").addObject().put("item_id",p.memberId()).putArray("entity_ids").add(p.entityId()).add("fictional-other-entity");context.putArray("version_eligible_item_ids");var q=context.putArray("catalog_version_qualifications");if(!unknown){var typed=p.resultConstraint();if(typed.versionChanged())context.withArray("version_eligible_item_ids").add(p.memberId());var row=q.addObject().put("item_id",p.memberId()).put("entity_id",p.entityId()).put("version_changed",typed.versionChanged());row.putObject("previous_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash",typed.previousProofHash());row.putObject("new_evidence_ref").put("kind","catalog_version_evidence").put("proof_hash",typed.newProofHash());}var ctx=FrozenApplicationContext.fromJson(context);var temporary=ctx.input(root,"fictional-dedup-attempt","c".repeat(64),0);var snapshot=JsonMapper.shared().createObjectNode().put("schema_version","input-v1").put("logical_key","fictional-catalog-dedup-key").put("generation",1).put("stage",f.category+"_dedup").put("cutoff",p.toJson().get("cutoff").asText());snapshot.set(FrozenApplicationContext.FIELD,ctx.toJson());if(frame)snapshot.set(FrozenCatalogVersionProjections.FIELD,FrozenCatalogVersionProjections.create(unknown?List.of():List.of(p),temporary).toJson());originalJson=JdbcFrozenInputs.canonical(snapshot);String hash=CanonicalJson.hash(CanonicalJson.Domain.INPUT,snapshot);original=ctx.input(root,"fictional-dedup-attempt",hash,0);f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-catalog-input-seed",root,hash),k->null,a->{var records=new JdbcJobRecords(f.source);records.ensureIntent(new JdbcJobRecords.Intent("fictional-catalog-dedup-intent","fictional-catalog-dedup-key",1,f.category+"_dedup",LocalDate.of(2026,1,1)),f.clock.instant());records.createRoot(new JdbcJobRecords.Root(root,"fictional-catalog-dedup-intent","fictional-catalog-dedup-key",1,0,f.category+"_dedup",fake.stage().priority()),f.clock.instant());new JdbcFrozenInputs(f.source).save(root,originalJson,hash,f.clock.instant());f.jdbc.update("UPDATE jobs SET input_cutoff_at=? WHERE id=?",java.sql.Timestamp.from(f.clock.instant()),root);return true;});}
    CatalogVersionBatchPreflightService batches(){return new CatalogVersionBatchPreflightService(f.source,f.tx,f.category);}
    @Test void FourCategoryNativeOriginalFrameCapturesExactFreshPermissionsBeforeAnyWriter(){for(String cat:List.of("agent","skill","workflow","model")){initialize(cat,false);seed(false,true);var batches=batches();var result=batches.capture(original);assertEquals(original,result.input());assertEquals(originalJson,result.snapshot());assertEquals(1,result.permissions().size());assertTrue(result.committed().isEmpty());assertTrue(result.frozen().entries().get(previous.memberId()).matches(result.permissions().get(previous.memberId()).projection()));f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-preflight-verify","fictional-root","c".repeat(64)),k->null,a->{assertEquals(previous.hash(),batches.permits().verify(result.permissions().get(previous.memberId())).hash());return true;});assertEquals(0,new JdbcJobRecords(f.source).byId(root).callCount());assertEquals(1,f.sends);}}
    @Test void ExistingFirstNegativeLedgerSkipsChangedOrMissingCurrentSourceProof(){seed(false,true);var i=input(previous);var value=CatalogVersionJudgmentValue.create(previous,i,result(i,payload(previous,false))).orElseThrow();f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-first-version-seed","fictional-root",value.hash()),k->null,a->{new JdbcCatalogVersionJudgments(f.source).append(value.judgmentKey(),CatalogVersionJudgmentLedger.receipt(value,null,null,f.clock.instant()),f.clock.instant());return true;});f.jdbc.update("DELETE FROM source_runs");f.jdbc.update("UPDATE analyzed_entities SET analysis_generation=3,revision=revision+1");var result=batches().capture(original);assertTrue(result.permissions().isEmpty());assertEquals("changed_declined",result.committed().get(previous.memberId()).verdict());assertEquals(3,f.jdbc.queryForObject("SELECT analysis_generation FROM analyzed_entities",Integer.class));assertEquals(1,f.sends);}
    @Test void MissingOriginalFrameUnknownAndKnownFalseNeverAcquireUnprovedPositivePermissions(){seed(false,false);assertThrows(RuntimeException.class,()->batches().capture(original));initialize("agent",false);seed(true,true);assertTrue(batches().capture(original).permissions().isEmpty());initialize("agent",false);current=f.catalogPayload();update();seed(false,true);assertFalse(batches().capture(original).permissions().get(previous.memberId()).projection().versionChanged());assertEquals(1,f.sends);}
    @Test void CurrentMetadataWrongContextOrCorruptOriginalChunkCannotBeReplacedByRehashing(){seed(false,true);current.put("summary","Fictional later");update();assertThrows(RuntimeException.class,()->batches().capture(original));initialize("agent",false);seed(false,true);f.jdbc.update("UPDATE jobs SET payload_hash=? WHERE owner_job_id=? AND purpose='input'",new byte[32],root);assertThrows(RuntimeException.class,()->batches().capture(original));initialize("agent",false);seed(false,true);var bad=new Input(original.rootId(),original.attemptId(),original.stage(),original.generation(),original.inputHash(),original.expectedRootRevision(),original.expectedContentRevision(),original.itemIds(),original.candidatesByItem(),original.eligibleHighValueItems(),original.allowedCitationIds(),Set.of(),original.targetEntityId(),original.periodStart(),original.periodEnd(),original.valueResultVersion(),original.dedupResultVersion(),original.catalogVersionQualifications());assertThrows(RuntimeException.class,()->batches().capture(bad));}
    @Test void OuterTransactionBadNativeRoleKeyCutoffAndWrongHashRejectWithoutImplicitSnapshot(){seed(false,true);assertThrows(RuntimeException.class,()->new TransactionTemplate(f.tx).execute(s->batches().capture(original)));for(String fault:List.of("task_type='news_value'","logical_key='fictional-foreign'","input_cutoff_at='2025-01-01 00:00:00'")){initialize("agent",false);seed(false,true);f.jdbc.update("UPDATE jobs SET "+fault+" WHERE id=?",root);assertThrows(RuntimeException.class,()->batches().capture(original));}assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='catalog_version_judgment'",Integer.class));assertEquals(1,f.sends);}
}
